import{_ as o,c as t,o as s,ah as n,ao as a,ap as i}from"./chunks/framework.Dq2_gudl.js";const y=JSON.parse('{"title":"Permission to Grieve — God Keeps Your Tears in a Bottle","description":"Crying for a pet is not weak faith. The Psalms say God collects our tears in a bottle and records them in His book.","frontmatter":{"title":"Permission to Grieve — God Keeps Your Tears in a Bottle","description":"Crying for a pet is not weak faith. The Psalms say God collects our tears in a bottle and records them in His book."},"headers":[],"relativePath":"en/pets-in-heaven/permission-to-grieve.md","filePath":"en/pets-in-heaven/permission-to-grieve.md"}'),r={name:"en/pets-in-heaven/permission-to-grieve.md"};function l(p,e,h,d,c,m){return s(),t("div",null,[...e[0]||(e[0]=[n('<div class="pl-quote"><p>“It&#39;s been months and I&#39;m still crying. Am I not strong enough? Is my faith too small?”</p><p class="pl-quote-soft">The Bible never treats tears as evidence of failure. Quite the opposite.</p></div><section class="pl-section"><h2>1. God keeps tears in a bottle</h2><blockquote><p><strong>Psalm 56:8</strong></p><p>&quot;Thou tellest my wanderings: put thou my tears into thy bottle: are they not in thy book?&quot;</p></blockquote><p>David wrote this from deep suffering. He asks God to store his tears in a bottle and record them in a book — in the ancient world, a bottle of tears was a precious collection, proof that “this person wept over this.”</p><p>Which means: <strong>your tears are not something that simply falls and disappears.</strong> Not one drop is wasted. Every tear you shed for them is collected. It is recorded.</p><p>So when you think, “am I crying too much?” — remember, to God that is not noise. That is a record.</p></section><section class="pl-section"><h2>2. God comes near the brokenhearted — He doesn&#39;t scold them</h2><blockquote><p><strong>Psalm 34:18</strong></p><p>&quot;The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.&quot;</p></blockquote><blockquote><p><strong>Psalm 147:3</strong></p><p>&quot;He healeth the broken in heart, and bindeth up their wounds.&quot;</p></blockquote><p>Notice the verbs: He <em>comes near</em>. He <em>heals</em>. He <em>bandages</em>. The first thing God does for the grieving is not to demand they pull themselves together — it is to walk over to them.</p><p>Jesus said one short sentence too:</p><blockquote><p><strong>Matthew 5:4</strong></p><p>&quot;Blessed are they that mourn: for they shall be comforted.&quot;</p></blockquote><p>“Blessed are those who mourn.” The grieving are not reprimanded — they are pronounced blessed, because comfort is coming. Not “you should cheer up,” but “you will be comforted.”</p></section><section class="pl-section"><h2>3. Grief is not the opposite of love — it&#39;s love continuing</h2><p>We don&#39;t cry over what we never loved. The reason it hurts this much is that there really was love between you.</p><p>God made us as beings who weep over loss. Jesus Himself wept at Lazarus&#39;s tomb (John 11:35) — knowing that in minutes He would raise him from the dead, He still wept.</p><p>So you don&#39;t owe anyone an apology for your tears. You are not short on faith. You are simply wounded in love.</p><p class="pl-quote-soft">If you&#39;d like, you can pray this:</p></section><div class="pl-quote"><p>“Lord, You know how many times I&#39;ve cried.<br>Thank You for not rushing me to get better, and for keeping every tear in Your bottle.<br>Come near to me, as You come near to everyone brokenhearted;<br>heal me, and please care for the one I miss.<br>Today I don&#39;t want to be strong. I only want to be held by You. Amen.”</p></div><section class="pl-section"><h2>Four things you can do for yourself now</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🌊</span><h3>Don&#39;t decide anything at the peak</h3><p>Grief waves pass. In the worst moment, all you have to do is survive the next five minutes. Handle nothing else.</p></div><div class="pl-moment"><span class="pl-moment-icon">🍽️</span><h3>Take care of your body first</h3><p>Drink water. Eat something. Sleep. Grief drains the body, and a hungry body makes the heart hurt more.</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>Write them into a notebook</h3><p>It doesn&#39;t need to be beautiful. Write one detail: how they woke you, your favourite expression of theirs. Give the missing somewhere to go.</p></div><div class="pl-moment"><span class="pl-moment-icon">🤝</span><h3>Find someone who truly understands</h3><p>Not everyone understands weeping for an animal, but some people do. If you can&#39;t find them, write it down — God can read it.</p></div></div></section><section class="pl-section"><h2>That day will come</h2><p>Revelation promises that one day God Himself will wipe every tear from our eyes, and there will be no more death, sorrow, crying, or pain (Revelation 21:4). On that day you will find that every tear you shed for them was both remembered and answered by a good God.</p><p>Until then — give yourself permission to grieve. It is one more way you can still love them.</p><p><a href="/en/pets-in-heaven/">← Back to Pets in Heaven</a> ｜ Back to the first reading: <a href="/en/pets-in-heaven/will-i-see-my-pet-again">Will I See My Pet Again?</a></p></section><div class="pl-cta"><h2>Today, one sentence is enough.</h2><p>PetLoss includes a guided journal and an SOS companion that offers grounding words in the heaviest moments. No account, no uploads, fully offline.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Download on the App Store</a></div><div class="pl-bible"><h3>Let the words of Scripture stay with you</h3><p>Every verse in this article comes from the Bible. With Rainbow Bible you can read Scripture anytime and set a daily verse widget — a small light for the days you miss them.</p><div class="pl-bible-shots"><figure><img src="'+a+'" alt="Rainbow Bible home-screen widget showing 2 Timothy 2:13" loading="lazy"><figcaption>Daily verse on your Home Screen</figcaption></figure><figure><img src="'+i+'" alt="Rainbow Bible app — Pets in Heaven topic showing Matthew 10:29-31" loading="lazy"><figcaption>Read Scripture in the Pets in Heaven topic</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Get Rainbow Bible on the App Store</a></div>',9)])])}const f=o(r,[["render",l]]);export{y as __pageData,f as default};
